
CREATE TABLE semesters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),semester_number int NOT NULL CHECK(semester_number>0),name text NOT NULL,academic_year text NOT NULL,starts_at timestamptz,ends_at timestamptz,is_current boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,id),UNIQUE(batch_id,semester_number),CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>=starts_at));
CREATE UNIQUE INDEX semester_current ON semesters(batch_id) WHERE is_current;
CREATE TABLE modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),semester_id uuid NOT NULL,module_code text NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',lecturer_name text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,id),UNIQUE(batch_id,semester_id,module_code),FOREIGN KEY(batch_id,semester_id) REFERENCES semesters(batch_id,id));
